// Aggregate all raw inputs into structured candidate items
const newsXml = $items('Fetch Legal News RSS')[0]?.json?.data || '';
const courtData = $items('Fetch Recent Court Decisions')[0]?.json?.results || [];
const aiXml = $items('Fetch AI Legal Developments RSS')[0]?.json?.data || '';
const existingTopics = $items('Read Existing Topics From Sheet').map(i => (i.json.title_idea || '').toLowerCase());

const rawCandidates = [];

// Basic XML Title Extractor for RSS feeds
function extractRssTitles(xmlStr, category) {
  const regex = /<item>([\s\S]*?)<\/item>/gi;
  let match;
  while ((match = regex.exec(xmlStr)) !== null) {
    const itemContent = match[1];
    const titleMatch = itemContent.match(/<title><!\[CDATA\[(.*?)\]\]><\/title>/i) || itemContent.match(/<title>(.*?)<\/title>/i);
    const linkMatch = itemContent.match(/<link>(.*?)<\/link>/i);
    if (titleMatch && titleMatch[1]) {
      rawCandidates.push({
        rawTitle: titleMatch[1].replace(/&amp;/g, '&'),
        sourceUrl: linkMatch ? linkMatch[1] : '',
        category: category
      });
    }
  }
}

extractRssTitles(newsXml, 'Legal News');
extractRssTitles(aiXml, 'AI Legal Developments');

// Add court rulings
courtData.slice(0, 10).forEach(courtItem => {
  if (courtItem.case_name || courtItem.plain_text) {
    rawCandidates.push({
      rawTitle: courtItem.case_name || 'Recent Federal Court Ruling',
      sourceUrl: courtItem.absolute_url || '',
      category: 'Court Decisions'
    });
  }
});

// Deduplicate candidates against existing sheet records
const filtered = rawCandidates.filter(c => {
  const normalized = c.rawTitle.toLowerCase().trim();
  return !existingTopics.some(existing => existing.includes(normalized) || normalized.includes(existing));
});

return [{
  json: {
    totalDiscovered: rawCandidates.length,
    uniqueCandidates: filtered.slice(0, 20),
    existingCount: existingTopics.length
  }
}];

// Parse OpenAI JSON array and generate unique IDs
const rawOutput = $json.message?.content || $json.text || '';
let parsed = [];

try {
  const cleaned = rawOutput.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = [];
}

if (!Array.isArray(parsed)) {
  parsed = [];
}

const now = new Date().toISOString();
const results = parsed.map((item, index) => {
  return {
    json: {
      topic_id: `TOPIC-${Date.now()}-${index + 1}`,
      title_idea: item.title_idea || 'Untitled Legal Topic',
      primary_keyword: item.primary_keyword || '',
      target_state: item.target_state || 'Federal',
      practice_area: item.practice_area || 'General Law',
      source_type: item.source_type || 'news',
      relevance_score: Number(item.relevance_score) || 75,
      status: 'NEW',
      suggested_date: now.split('T')[0],
      notes: item.notes || 'Automated research discovery',
      created_at: now
    }
  };
});

return results.length > 0 ? results : [{
  json: {
    status: 'NO_NEW_TOPICS_ABOVE_THRESHOLD',
    timestamp: now
  }
}];
